L["that string is incomplete or has been changed -- copy it again in one piece, and paste a long one into the box under Share settings on the General tab of the options."] = "quella stringa è incompleta o è stata modificata -- copiala di nuovo tutta intera, e incolla quelle lunghe nella casella sotto Condividi impostazioni, nella scheda Generale delle opzioni."
L["that string is damaged -- part of it is not a setting Manners can read. Copy it again in one piece."] = "quella stringa è danneggiata -- una sua parte non è un'impostazione che Manners sa leggere. Copiala di nuovo tutta intera."
L["that string gives %s a value it cannot have, so nothing was changed."] = "quella stringa dà a %s un valore che non può avere, quindi non è stato cambiato niente."
L["settings imported -- every one of them is the default."] = "impostazioni importate -- sono tutte quelle predefinite."
L["settings imported -- 1 differs from the defaults."] = "impostazioni importate -- 1 è diversa da quelle predefinite."
L["settings imported -- %d differ from the defaults."] = "impostazioni importate -- %d sono diverse da quelle predefinite."
L["1 setting from a newer version of Manners was left out."] = "1 impostazione di una versione più recente di Manners è stata tralasciata."
L["%d settings from a newer version of Manners were left out."] = "%d impostazioni di una versione più recente di Manners sono state tralasciate."
L["The string had speaking a line when you buff switched on. That is left off, because it talks to other players: switch it on under When you click if you want it."] = "Nella stringa era attiva l'opzione per dire una frase quando dai un beneficio. Resta disattivata, perché parla agli altri giocatori: attivala nella scheda Al clic se la vuoi."
L["What you say when you buff, and where, is kept as you had it, because you have speaking switched on."] = "Cosa dici quando dai un beneficio, e dove, resta com'era, perché tu hai già attivato le frasi."
L["The prompt's look changes when this fight ends."] = "L'aspetto del riquadro cambia quando finisce questo combattimento."
L["|cffffd100/manners import undo|r puts your old settings back."] = "|cffffd100/manners import undo|r ripristina le impostazioni precedenti."
L["nothing to undo -- no settings have been imported on this profile this session."] = "niente da annullare -- in questa sessione non sono state importate impostazioni in questo profilo."
L["nothing to undo on this profile -- the last import was made on profile %s. Switch back to it to undo it."] = "niente da annullare in questo profilo -- l'ultima importazione è stata fatta nel profilo %s. Torna a quel profilo per annullarla."
L["nothing to undo on this profile -- the last import was made on another one. Switch back to it to undo it."] = "niente da annullare in questo profilo -- l'ultima importazione è stata fatta in un altro profilo. Torna a quel profilo per annullarla."
L["your settings from before the import could not be read back, so they were not restored."] = "non è stato possibile rileggere le impostazioni di prima dell'importazione, quindi non sono state ripristinate."
L["your settings from before the import are back. The prompt's look changes when this fight ends."] = "sono tornate le impostazioni di prima dell'importazione. L'aspetto del riquadro cambia quando finisce questo combattimento."
L["your settings from before the import are back."] = "sono tornate le impostazioni di prima dell'importazione."
L["Everyday"] = "Uso quotidiano"
L["Setting it up"] = "Configurazione"
L["Sharing settings"] = "Condividere le impostazioni"
L["When something is wrong"] = "Quando qualcosa non va"
L["open the options window"] = "apri la finestra delle opzioni"
L["turn the addon on"] = "attiva l'add-on"
L["turn it off"] = "disattivalo"
L["hide the prompt for a while -- 15 minutes unless you say"] = "nascondi il riquadro per un po' -- 15 minuti, se non indichi altro"
L["preview the prompt with a mock candidate"] = "mostra un'anteprima del riquadro con un candidato finto"
L["the favour ledger: who buffed you, what you gave back, and who you buffed"] = "il registro dei favori: chi ti ha dato un beneficio, cosa hai ricambiato e a chi hai dato un beneficio"
L["what this addon does, and the one thing it needs from you"] = "cosa fa questo add-on, e l'unica cosa che ti chiede"
L["make a /click macro for your action bar"] = "crea una macro /click per la barra delle azioni"
L["unlock the prompt so it can be dragged"] = "sblocca il riquadro per poterlo trascinare"
L["lock it again -- an unlocked prompt never casts"] = "bloccalo di nuovo -- un riquadro sbloccato non lancia mai niente"
L["list who is never offered anything, or put somebody on that list"] = "elenca chi non viene mai proposto, o aggiungi qualcuno agli esclusi"
L["take somebody off the never-offer list"] = "togli qualcuno dagli esclusi"
L["switch handing your target back after buffing on or off"] = "attiva o disattiva il ripristino del bersaglio dopo aver dato un beneficio"
L["switch the chat lines about who buffed you on or off"] = "attiva o disattiva le righe in chat su chi ti ha dato un beneficio"
L["copy these settings as one line of text"] = "copia queste impostazioni come un'unica riga di testo"
L["use settings somebody exported, or undo the last import"] = "usa le impostazioni esportate da qualcuno, o annulla l'ultima importazione"
L["what your class and this build allow"] = "cosa permettono la tua classe e questo client"
L["the last few things that broke"] = "gli ultimi errori"
L["tools for testing the addon on this client: the click log, try, look and forms"] = "strumenti per testare l'add-on su questo client: il log dei clic, try, look e forms"
L["log what the button does when clicked"] = "scrivi in chat cosa fa il pulsante quando ci fai clic"
L["run any macro text from the prompt"] = "esegui qualsiasi testo di macro dal riquadro"
L["dump every API answer for a unit"] = "mostra ogni risposta dell'API per un'unità"
L["example macros to try"] = "esempi di macro da provare"
L["Manners commands:"] = "Comandi di Manners:"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "|cffffd100/mnr|r funziona al posto di |cffffd100/manners|r in tutti i comandi."
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try annullato -- il lancio normale torna quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["try cleared -- back to the normal cast."] = "try annullato -- si torna al lancio normale."
L["try armed: |cff80ff80%s|r"] = "try attivato: |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080per ora non attivato:|r %s."
L["expands to: |cffffffff%s|r"] = "diventa: |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d caratteri -- %d oltre i %d che il testo di una macro può contenere. Il client lo taglierà, e ciò che viene eseguito non è ciò che vedi qui sopra."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante. |cffffd100/manners try|r da solo lo annulla."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Il riquadro lo attiva appena il giocatore ne ha uno. |cffffd100/manners try|r da solo lo annulla."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Fai clic sul riquadro per eseguirlo. |cffffd100/manners try|r da solo lo annulla."
L["Targeting forms, for /manners try:"] = "Modi di indicare il bersaglio, per /manners try:"
L["(on yourself)"] = "(su di te)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Segnaposto: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} è il nome sotto cui si registra un debito, {aim} è ciò che serve a una riga di bersaglio. Usa \\n per andare a capo."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "il registro dei favori non si è caricato -- reinstallare Manners dovrebbe riportarlo."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "sbloccato -- potrai trascinarlo quando finisce questo combattimento; fino ad allora un clic lancia ancora ciò che il combattimento ha congelato. Poi |cffffd100/manners lock|r."
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "sbloccato -- potrai trascinarlo quando finisce questo combattimento; nel frattempo il pulsante è vuoto. Poi |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "sbloccato -- trascina il riquadro, poi |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "sbloccato, ma l'add-on è |cffff8080disattivato|r, quindi non c'è nessun riquadro da trascinare -- prima |cffffd100/manners on|r."
L["locked."] = "bloccato."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "ripristino del bersaglio dopo un beneficio: |cff00ff00attivato|r -- ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "ripristino del bersaglio dopo un beneficio: |cffff0000disattivato|r -- ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["hand your target back after buffing: |cff00ff00on|r"] = "ripristino del bersaglio dopo un beneficio: |cff00ff00attivato|r"
L["hand your target back after buffing: |cffff0000off|r"] = "ripristino del bersaglio dopo un beneficio: |cffff0000disattivato|r"
L["click logging: |cff00ff00on|r"] = "log dei clic: |cff00ff00attivato|r"
L["click logging: |cffff0000off|r"] = "log dei clic: |cffff0000disattivato|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "verbose: |cff00ff00attivato|r -- una riga nella tua chat quando qualcuno ti dà un beneficio, quando un favore viene considerato ricambiato, e quando un clic fallisce, viene saltato o lascia un favore da ricambiare"
L["verbose: |cffff0000off|r"] = "verbose: |cffff0000disattivato|r"
L["enabled."] = "attivato."
L["disabled."] = "disattivato."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "non c'è nessuno tra i tuoi esclusi. Fai Maiusc+clic destro sul riquadro per aggiungere agli esclusi il giocatore che mostra."
L["never offered anything unless they buff you: %s"] = "mai proposti, a meno che non ti diano un beneficio: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "indica chi: |cffffd100/manners allow Name|r. |cffffd100/manners never|r elenca tutti gli esclusi."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r può di nuovo essere proposto."
L["nobody called %s is on your never-offer list."] = "tra i tuoi esclusi non c'è nessuno che si chiami %s."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze accetta un numero di minuti da 1 a %d, oppure off -- per esempio |cffffd100/manners snooze 15|r o |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share settings|r on the General tab of the options -- click in it, select all and copy."] = "le tue impostazioni sono nella casella sotto |cffffd100Condividi impostazioni|r nella scheda Generale delle opzioni -- fai clic nella casella, seleziona tutto e copia."
L["this string is too long to be imported back -- a very long phrase box under When you click is the usual cause. Shorten it if you want to share these settings."] = "questa stringa è troppo lunga per essere reimportata -- di solito la causa è una casella delle frasi molto lunga nella scheda Al clic. Accorcia le frasi se vuoi condividere queste impostazioni."
L["paste the settings string into the box under |cffffd100Share settings|r on the General tab, or type |cffffd100/manners import|r followed by it."] = "incolla la stringa delle impostazioni nella casella sotto |cffffd100Condividi impostazioni|r nella scheda Generale, oppure scrivi |cffffd100/manners import|r seguito dalla stringa."
L["type |cffffd100/manners import|r followed by a settings string."] = "scrivi |cffffd100/manners import|r seguito da una stringa delle impostazioni."
L["Tools for testing Manners on this client:"] = "Strumenti per testare Manners su questo client:"
L["nothing has broken this session."] = "in questa sessione non è andato storto niente."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100gli ultimi %d di %d|r |cff808080(%d conservati)|r:"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100gli ultimi %d di %d|r:"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua non si è caricato -- controlla l'elenco dei file del toc"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040questo client non conosce %s|r -- Manners ha gli ID incantesimo sbagliati per %s su %s. Segnala questa riga, per favore."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "da ricambiare: |cffffffff%s|r (%d s rimasti, ti ha dato un beneficio %d s fa)"
L["not watching for favours -- Manners is switched off."] = "nessun controllo dei favori -- Manners è disattivato."
L["not watching for favours -- |cffffd100People who buffed me|r is switched off."] = "nessun controllo dei favori -- l'opzione |cffffd100Chi mi ha dato un beneficio|r è disattivata."
L["nobody has buffed you recently."] = "nessuno ti ha dato un beneficio di recente."
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080benefici su di te: ultima scansione non attendibile (%s)|r -- %d letti, riferimento %d"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100benefici su di te: riferimento non stabilito|r -- %d letti, in attesa di una seconda scansione che confermi"
L["own buffs: %d read, baseline %d"] = "benefici su di te: %d letti, riferimento %d"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "DISATTIVATO in questo profilo -- non si registra né si propone niente; /manners on"
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "il riquadro è SBLOCCATO -- non darà benefici a nessuno finché non scrivi /manners lock"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100in pausa fino alle %s|r -- nessun riquadro fino ad allora; /manners snooze off la termina"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100in sella|r -- l'opzione Non in sella tiene nascosto il riquadro finché non scendi dalla cavalcatura"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try è attivato:|r %s -- annullalo con /manners try da solo"
L["queue now: %d"] = "in coda ora: %d"
L["queue if switched on: %d"] = "in coda se attivato: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "non esiste |cffffd100/manners %s|r -- intendevi |cffffd100/manners %s|r? |cffffd100/manners help|r li elenca tutti."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "non esiste |cffffd100/manners %s|r -- intendevi |cffffd100/manners %s|r? |cffffd100/manners dev|r elenca gli strumenti di test."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "Grazie di cuore, {name}! Alla forgia il primo giro lo offro io."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Grazie assai, {name}. Ora hai un amico nella montagna."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "Ma certo, {name}, bastava chiedere! E ora non muoverti."
L["Say no more, {name}. Stone and steel, here it comes."] = "Non dire altro, {name}. Pietra e acciaio, eccolo che arriva!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "Tieni, {name}, un aiutino per tenerti in piedi."
L["Off ye go, {name}, steady as the mountain."] = "Va' pure, {name}, con passo saldo come la montagna."
L["Stone and hammer keep ye, cousin {name}!"] = "Pietra e martello ti proteggano, {name}! Siamo della stessa roccia."
L["My thanks, {name}. Allow me to return the kindness."] = "Ti ringrazio, {name}. Permettimi di ricambiare la cortesia."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Molto gentile, {name}. Nessuno dirà che dimentichiamo gli amici."
L["Of course, {name}. Stand fast a moment."] = "Certo, {name}. Non muoverti per un istante."
L["Right away, {name}. Keep your shield high."] = "Subito, {name}. Tieni alto lo scudo."
L["The road ahead is long, {name}. Take this with you."] = "La strada è lunga, {name}. Porta questo con te."
L["Fair winds and following seas, {name}."] = "Buon vento e mare calmo, {name}."
L["Arathor's children stand together, {name}."] = "I figli di Arathor restano uniti, {name}."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. Ricambio la tua gentilezza."
L["Thank you, {name}. Elune smiles on the generous."] = "Grazie, {name}. Elune sorride a chi è generoso."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "Con gioia, {name}. Resta immobile e lascia che la luna ti trovi."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Certo, {name}. Le benedizioni di Elune vanno condivise."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. Cammina lieve sotto le stelle."
L["May the forest shelter you, {name}, wherever you roam."] = "Che la foresta ti protegga, {name}, ovunque tu vada."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. Elune tiene vicini i suoi figli."
L["The shadows remember kindness, {name}. So do I."] = "Le ombre ricordano la gentilezza, {name}. E anch'io."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Ti ringrazio, {name}. I ren'dorei non dimenticano una gentilezza."
L["As you wish, {name}. The shadows answer kindly today."] = "Come desideri, {name}. Oggi le ombre sono benevole."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "Consideralo fatto, {name}. Il Vuoto obbedisce a noi, non il contrario."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Un tocco d'ombra per te, {name}. Del tutto sicuro. Quasi."
L["Walk carefully in the dark places, {name}."] = "Cammina con cautela nei luoghi oscuri, {name}."
L["We ren'dorei look after our own, {name}."] = "Noi ren'dorei ci prendiamo cura dei nostri, {name}."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "Grazie, {name}! Gentilezza ricevuta, catalogata e restituita!"
L["Reciprocity engaged! Much obliged, {name}."] = "Reciprocità attivata! Grazie mille, {name}."
L["Request received, {name}! Processing... done!"] = "Richiesta ricevuta, {name}! Elaborazione... fatto!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "Un potenziamento in arrivo, {name}! Non muoverti, devo calibrare."
L["Hold still, {name}, this is perfectly safe. Probably!"] = "Non muoverti, {name}, è perfettamente sicuro. Probabilmente!"
L["Science says you need this, {name}. Who am I to argue?"] = "La scienza dice che ti serve, {name}. Chi sono io per contraddirla?"
L["A small upgrade for you, {name}. No cogs required."] = "Un piccolo potenziamento per te, {name}. Senza ingranaggi."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "Per Gnomeregan, {name}! Che bello parlare con qualcuno alla mia altezza."
L["The Light rewards kindness, {name}, and so shall I."] = "La Luce premia la gentilezza, {name}, e così farò anch'io."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. Ricambio il tuo dono."
L["Of course, {name}. May the Naaru guide your steps."] = "Certo, {name}. Che i Naaru guidino i tuoi passi."
L["Gladly, {name}. The Light answers those who ask."] = "Con piacere, {name}. La Luce risponde a chi chiede."
L["The Light is with you, {name}. Go in peace."] = "La Luce è con te, {name}. Va' in pace."
L["Walk in the Light, {name}. May it shelter you always."] = "Cammina nella Luce, {name}. Che ti protegga sempre."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name}! I figli di Argus si prendono cura l'uno dell'altro."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Grazie infinite, {name}. Gilneas non dimentica mai una gentilezza."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Grazie, {name}. Hai la mia gratitudine, e il mio ululato migliore."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Certamente, {name}. Non muoverti, non mordo. Non troppo."
L["Right you are, {name}. Stand steady now."] = "Senz'altro, {name}. Ora non muoverti."
L["Stay off the moors after dark, {name}. Take this."] = "Evita le brughiere dopo il tramonto, {name}. Prendi questo."
L["Keep your wits about you, {name}. Something is always hunting."] = "Tieni gli occhi aperti, {name}. C'è sempre qualcosa a caccia."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "La maledizione ci lega, {name}, ma Gilneas ci lega ancora di più."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name}! L'onore è ripagato."
L["You give freely, {name}. I return the favour."] = "Tu doni senza chiedere, {name}. Io ricambio il favore."
L["Dabu, {name}. It is done."] = "Dabu, {name}. È fatto."
L["Hold still, {name}. Strength for the fight ahead."] = "Non muoverti, {name}. Forza per la battaglia che ti aspetta."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name}! Portalo con te in battaglia."
L["Blood and thunder, {name}! Go and earn your glory."] = "Sangue e tuono, {name}! Va' e conquista la tua gloria."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name}! Il sangue dei clan scorre forte in te."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Grazie, {name}. Mi scalderebbe il cuore, se battesse ancora."
L["Such warmth, for one so cold? Returned in full, {name}."] = "Tanto calore per chi è così freddo? Te lo rendo tutto, {name}."
L["Certainly, {name}. Try not to die. It's overrated."] = "Certo, {name}. Cerca di non morire. È sopravvalutato."
L["You need only ask, {name}. The dead are patient."] = "Basta chiedere, {name}. I morti sono pazienti."
L["Stay among the living a little longer, {name}."] = "Resta tra i vivi ancora un po', {name}."
L["Take this, {name}. The grave can wait."] = "Prendi, {name}. La tomba può aspettare."
L["We Forsaken must look after each other, {name}."] = "Noi Reietti dobbiamo badare l'uno all'altro, {name}."
L["The Earth Mother sees your kindness, {name}. I return it."] = "La Madre Terra vede la tua gentilezza, {name}. Io la ricambio."
L["Thank you, {name}. May the winds guide you."] = "Grazie, {name}. Che i venti ti guidino."
L["Of course, {name}. Stand tall and be at peace."] = "Certo, {name}. Tieni alta la testa e resta in pace."
L["Ask and it is given, {name}. The herd shares what it has."] = "Chiedi e ti sarà dato, {name}. La mandria divide ciò che ha."
L["Walk with the Earth Mother, {name}."] = "Cammina con la Madre Terra, {name}."
L["May An'she light your path, {name}."] = "Che An'she illumini il tuo cammino, {name}."
L["The Earth Mother watches over us both, {name}."] = "La Madre Terra veglia su di noi due, {name}."
L["Ya be too kind, {name}! Dis one be from me."] = "Si' troppo gentile, {name}! Chisto t'o dong' io."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "Grazie assaje, cumpà! 'E spiriti te sorrideno, {name}."
L["Sure ting, {name}. Hold still now."] = "Sicuro, {name}. Mo' nun te movere."
L["No worries, {name}. Da loa got ya covered."] = "Nun te preoccupà, {name}. Ce pensano 'e loa."
L["Da loa be watchin' over ya, {name}."] = "'E loa te guardano 'e spalle, {name}."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Occhi aperti llà fore, {name}. Pigliate chisto."
L["Hey, {name}! Always good to see family, mon."] = "Uè, {name}! Fa sempre piacere vedé 'a famiglia, cumpà."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Tanta cortesia ti fa onore, {name}. Anar'alah belore."
L["How gracious, {name}. Allow me to return the favour."] = "Che gesto raffinato, {name}. Permettimi di ricambiare il favore."
L["Naturally, {name}. Only the finest for you."] = "Naturalmente, {name}. Solo il meglio per te."
L["For you, {name}? Of course. The sun gives freely."] = "Per te, {name}? Ma certo. Il sole dona senza riserve."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. Che il sole ti guidi."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. Combatti con eleganza."
L["The Sunwell shines for us both, {name}."] = "Il Pozzo Solare splende per noi due, {name}."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Prendo nota della tua generosità, {name}. Suramar ricorda i suoi amici."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Assai cortese, {name}. Permettimi di ricambiare come si conviene."
L["Of course, {name}. A little arcane polish, just for you."] = "Certo, {name}. Un po' di lustro arcano, solo per te."
L["A reasonable request, {name}. Granted."] = "Una richiesta ragionevole, {name}. Concessa."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Prendi, {name}. I doni arcani sono sprecati per chi sta in ozio."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Una scintilla dell'arcano di Suramar, {name}. Usala con saggezza."
L["Suramar's children shine together again, {name}."] = "I figli di Suramar tornano a brillare insieme, {name}."
L["A favour for a favour, {name}! Pleasure doing business."] = "Favore per favore, {name}! È un piacere fare affari con te."
L["Thanks, {name}! Consider your account settled in full."] = "Grazie, {name}! Il tuo conto è saldato per intero."
L["You got it, {name}! Time is money, friend!"] = "Detto fatto, {name}! Il tempo è denaro, amico!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "Affare fatto, {name}! Lo metto sul tuo conto. Scherzo!"
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "Questo lo offre la casa, {name}. Non dirlo al Principe del Commercio."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "Roba di prima scelta, zero commissioni, {name}. Solo per oggi!"
L["Anything for a fellow entrepreneur, {name}!"] = "Tutto per un collega imprenditore, {name}!"
L["Thank you, {name}! The caravan always repays a kindness."] = "Grazie, {name}! La carovana ricambia sempre una gentilezza."
L["How kind, {name}! You're on the caravan's good list now."] = "Che gentile, {name}! Ora sei nella lista dei buoni della carovana."
L["Of course, {name}! Shake the sand out and hold still."] = "Certo, {name}! Scuoti via la sabbia e non muoverti."
L["Coming right up, {name}! Caravan service, no waiting."] = "Arriva subito, {name}! Servizio carovana, niente attese."
L["Every traveller needs something for the road, {name}."] = "Ogni viandante merita qualcosa per il viaggio, {name}."
L["Keep this, {name}. The desert is long and the water is short."] = "Tienilo, {name}. Il deserto è lungo e l'acqua è poca."
L["A fellow wanderer! The caravan is never far, {name}."] = "Un compagno di strada! La carovana non è mai lontana, {name}."
L["A kindness returned is a kindness doubled, {name}."] = "Una gentilezza ricambiata è una gentilezza raddoppiata, {name}."
L["Thank you, {name}. You have restored my balance."] = "Grazie, {name}. Hai ristabilito il mio equilibrio."
L["Of course, {name}. Patience, and it is done."] = "Certo, {name}. Un po' di pazienza, ed è fatto."
L["With pleasure, {name}. A kind deed is never wasted."] = "Con piacere, {name}. Una buona azione non è mai sprecata."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Prendi, {name}. E dopo, magari, una tazza di tè?"
L["Balance in all things, {name}. Now go with a light heart."] = "Equilibrio in ogni cosa, {name}. Ora va' con il cuore leggero."
L["We must share a brew when the road allows, {name}!"] = "Dobbiamo farci una birra quando la strada lo permette, {name}!"
L["Your kindness is noted, {name}. Dragons do not forget."] = "Non scorderò la tua gentilezza, {name}. I draghi non dimenticano."
L["Thank you, {name}. Returned on swift wings."] = "Grazie, {name}. Ricambio su ali veloci."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Molto bene, {name}. Non muoverti, mi dispiacerebbe bruciacchiarti."
L["Granted, {name}. A dragon keeps its word."] = "Concesso, {name}. Un drago mantiene la parola."
L["Take this, {name}. Even a dragon needs allies."] = "Prendi, {name}. Anche un drago ha bisogno di alleati."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Un dono dalle Isole dei Draghi, {name}. Buon volo."
L["The Forbidden Reach feels far behind us now, {name}."] = "L'Isola Proibita ormai sembra così lontana, {name}."
L["It is good to see one of our own, {name}."] = "È bello vedere qualcuno della nostra gente, {name}."
L["Thank you, {name}. The Alliance looks after its own."] = "Grazie, {name}. L'Alleanza si prende cura dei suoi."
L["Kindness answered, {name}. For the Alliance!"] = "Gentilezza ricambiata, {name}. Per l'Alleanza!"
L["Of course, {name}. Allies help each other."] = "Certo, {name}. Gli alleati si aiutano a vicenda."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Subito, {name}. L'Alleanza non lascia un amico nel bisogno."
L["For the Alliance, {name}! Stay strong out there."] = "Per l'Alleanza, {name}! Tieni duro là fuori."
L["Onward, {name}. The Alliance is with you."] = "Avanti, {name}. L'Alleanza è con te."
L["Together we stand, {name}. For the Alliance!"] = "Uniti siamo forti, {name}. Per l'Alleanza!"
L["Strength and honour, {name}. Your kindness is repaid."] = "Forza e onore, {name}. La tua gentilezza è ripagata."
L["The Horde takes care of its own, {name}."] = "L'Orda non abbandona i suoi, {name}."
L["Consider it done, {name}. For the Horde."] = "Consideralo fatto, {name}. Per l'Orda."
L["You only had to ask, {name}. The Horde answers."] = "Bastava chiedere, {name}. L'Orda risponde."
L["For the Horde, {name}! Go with strength."] = "Per l'Orda, {name}! Va' e sii forte."
L["Go with honour, {name}. Victory awaits."] = "Va' con onore, {name}. La vittoria ti attende."
L["Our strength is each other, {name}. For the Horde!"] = "La nostra forza siamo noi, {name}. Per l'Orda!"
L["Thank you, {name}. Good hearts are found everywhere."] = "Grazie, {name}. I cuori buoni si trovano ovunque."
L["Gladly, {name}, whatever banner you fly."] = "Con piacere, {name}, qualunque sia il tuo stendardo."
L["Friends can come from any side, {name}."] = "Gli amici possono venire da ogni parte, {name}."
L["Side by side, {name}, whatever comes."] = "Fianco a fianco, {name}, qualunque cosa accada."
L["One good turn deserves another, {name}."] = "Una cortesia ne merita un'altra, {name}."
L["Have some {buff} in return, {name}."] = "In cambio, ecco {buff} per te, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "La gentilezza va ricambiata, {name}. Grazie."
L["You asked, {name}, and here it is."] = "Hai chiesto, {name}, ed ecco fatto."
L["{buff}, coming right up, {name}."] = "{buff} in arrivo, {name}."
L["Gladly, {name}. One moment."] = "Con piacere, {name}. Un attimo."
L["Safe travels, {name}. Take some {buff} with you."] = "Buon viaggio, {name}. Porta con te un po' di {buff}."
L["A small blessing for the road, {name}."] = "Una piccola benedizione per il viaggio, {name}."
L["Go well, {name}, and come back in one piece."] = "Buon cammino, {name}, e torna senza un graffio."
L["Everyone ready? You are now, {name}."] = "Tutti pronti? Ora lo sei anche tu, {name}."
L["A little something for the party, {name}."] = "Un pensierino per il gruppo, {name}."
L["Stay close, {name}. We go further together."] = "Stammi vicino, {name}. Insieme si va più lontano."
