L["You gave %d buffs unprompted today."] = "Oggi hai dato %d benefici di tua iniziativa."
L["All time -- received: %d, returned: %d, given to your group: %d, to strangers: %d"] = "Da sempre -- ricevuti: %d, ricambiati: %d, dati al tuo gruppo: %d, a sconosciuti: %d"
L["All time"] = "Da sempre"
