L["Hands your own target back afterwards."] = "Poi ripristina il tuo bersaglio."
L["They are already your target, so they stay targeted."] = "È già il tuo bersaglio, quindi resta tale."
L["|cffffcc66Leaves them targeted|r -- your own target is not restored."] = "|cffffcc66Lo lascia come bersaglio|r -- il tuo bersaglio non viene ripristinato."
L["Says: |cffffffff%s|r"] = "Dice: |cffffffff%s|r"
L["PREVIEW"] = "ANTEPRIMA"
L["preview off."] = "anteprima terminata."
L["|cffff8080not during a fight|r -- the preview can be shown once it ends."] = "|cffff8080non in combattimento|r -- potrai vedere l'anteprima quando il combattimento finisce."
L["somebody real is on the prompt, so there is nothing to preview -- open |cffffd100/manners|r to style it; a preview holds while that window is open."] = "c'è una persona vera nel riquadro, quindi non c'è niente da mostrare in anteprima -- apri |cffffd100/manners|r per personalizzarlo; l'anteprima resta finché quella finestra è aperta."
L["preview on -- it stays while the options window is open, then %ds longer, or |cffffd100/manners test|r to stop."] = "anteprima attiva -- resta finché la finestra delle opzioni è aperta, poi altri %d s, oppure |cffffd100/manners test|r per fermarla."
L["the prompt has moved on to |cffffffff%s|r -- press again to buff them."] = "il riquadro è passato a |cffffffff%s|r -- premi di nuovo per dargli un beneficio."
L["|cffff8080could not buff|r |cffffffff%s|r"] = "|cffff8080beneficio non dato a|r |cffffffff%s|r"
L["|cffff8080could not buff|r |cffffffffthem|r"] = "|cffff8080beneficio non dato al|r |cffffffffgiocatore|r"
L["|cffe8e0a0sent to|r |cffffffff%s|r"] = "|cffe8e0a0inviato a|r |cffffffff%s|r"
L["|cffe8e0a0sent to|r |cffffffffthem|r"] = "|cffe8e0a0inviato al|r |cffffffffgiocatore|r"
L["|cff8ce88cbuffed|r |cffffffff%s|r"] = "|cff8ce88cbeneficio dato a|r |cffffffff%s|r"
L["|cff8ce88cbuffed|r |cffffffffthem|r"] = "|cff8ce88cbeneficio dato al|r |cffffffffgiocatore|r"
L["the game confirmed it"] = "il gioco l'ha confermato"
L["still armed by the fight"] = "ancora armato dal combattimento"
L["nothing to buff"] = "nessun beneficio da dare"
L["nothing this character can cast -- a press still casts what the fight froze"] = "questo personaggio non ha nulla da lanciare -- premendo lanci ancora ciò che il combattimento ha congelato"
L["nothing this character can cast -- nothing armed, and the panel cannot go"] = "questo personaggio non ha nulla da lanciare -- pulsante vuoto, e il pannello non può sparire"
L["preview off -- timed out."] = "anteprima terminata -- tempo scaduto."
L["preview off -- somebody real turned up."] = "anteprima terminata -- è arrivata una persona vera."
L["Someone %d"] = "Qualcuno %d"
L["switched off -- a press still casts what the fight froze"] = "disattivato -- premendo lanci ancora ciò che il combattimento ha congelato"
L["switched off -- nothing armed, and the panel cannot go"] = "disattivato -- pulsante vuoto, e il pannello non può sparire"
L["Drag to move"] = "Trascina per spostare"
L["not buffing while unlocked"] = "nessun beneficio finché è sbloccato"
L["unlocked -- a press still casts what the fight froze"] = "sbloccato -- premendo lanci ancora ciò che il combattimento ha congelato"
L["unlocked -- nothing armed, and the panel cannot go"] = "sbloccato -- pulsante vuoto, e il pannello non può sparire"
L["held -- in combat"] = "fermo -- in combattimento"
L["held -- a press still casts what the fight froze"] = "fermo -- premendo lanci ancora ciò che il combattimento ha congelato"
L["held -- nothing armed, and the panel cannot go"] = "fermo -- pulsante vuoto, e il pannello non può sparire"
L["ready in %.1fs"] = "pronto tra %.1f s"
L["%s |cffffd100snoozed until %s|r"] = "%s |cffffd100in pausa fino alle %s|r"
L["%s |cffff8080off|r"] = "%s |cffff8080disattivato|r"
L["%s |cff80e0801 waiting|r"] = "%s |cff80e0801 in attesa|r"
L["%s |cff80e080%d waiting|r"] = "%s |cff80e080%d in attesa|r"
L["Automatic"] = "Automatico"
L["%s |cff808080(not learned)|r"] = "%s |cff808080(non imparato)|r"
L["%s |cff808080(mana users only)|r"] = "%s |cff808080(solo per chi usa il mana)|r"
L["%s |cff808080(your group only)|r"] = "%s |cff808080(solo il tuo gruppo)|r"
L["This character has nothing it can cast on another player."] = "Questo personaggio non ha nulla da lanciare su un altro giocatore."
L["You have not learned any of these yet, so nobody will be offered anything."] = "Non hai ancora imparato nessuno di questi incantesimi, quindi non verrà proposto nulla a nessuno."
L["Automatic never offers %s -- nobody standing in a city wants it -- so nobody will be offered anything."] = "Automatico non propone mai %s -- a nessuno in città serve -- quindi non verrà proposto nulla a nessuno."
L["Pin it in the dropdown above if you want it given out anyway."] = "Fissalo nel menu qui sopra se vuoi proporlo comunque."
L["Every spell you have learned is switched off, so nothing is offered until you switch one back on or learn one of the others."] = "Tutti gli incantesimi che hai imparato sono disattivati, quindi non viene proposto nulla finché non ne riattivi uno o non impari uno degli altri."
L["Every spell below is switched off, so the prompt will never appear."] = "Tutti gli incantesimi qui sotto sono disattivati, quindi il riquadro non apparirà mai."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. |cffffd100Always offer|r does not check what they carry, so it can replace one of yours."] = "Le tue benedizioni si sostituiscono a vicenda, quindi Automatico dà solo la prima tra %s adatta al giocatore. |cffffd100Proponi sempre|r non controlla quali benedizioni ha il giocatore, quindi può sostituire una delle tue."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Where the game hides which blessing somebody carries, it can replace one of yours."] = "Le tue benedizioni si sostituiscono a vicenda, quindi Automatico dà solo la prima tra %s adatta al giocatore. Dove il gioco nasconde quale benedizione ha qualcuno, può sostituire una delle tue."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Anybody already carrying one of yours is left alone."] = "Le tue benedizioni si sostituiscono a vicenda, quindi Automatico dà solo la prima tra %s adatta al giocatore. Chi ha già una delle tue viene lasciato stare."
L["Automatic offers the first of these they are missing, in this order: %s."] = "Automatico propone il primo di questi che gli manca, in quest'ordine: %s."
L["Where the game will not say what somebody is carrying, it moves down the list each time instead of offering the same one over and over."] = "Dove il gioco non dice quali benefici ha qualcuno, Automatico passa al successivo dell'elenco ogni volta invece di proporre sempre lo stesso."
L["Only |cffffffff%s|r is offered, to everybody, whatever else they are missing. The per-spell switches come back with Automatic."] = "Viene proposto solo |cffffffff%s|r, a tutti, qualunque altra cosa manchi loro. Le caselle dei singoli incantesimi tornano con Automatico."
L["You have pinned %s, which you have not learned."] = "Hai fissato %s, che non hai imparato."
L["Nothing will be offered to anybody until you learn it or switch back to Automatic."] = "Non verrà proposto nulla a nessuno finché non lo impari o non torni ad Automatico."
L["Switched off, this one is never offered to anybody and Automatic walks straight past it. Everything else carries on as before."] = "Se disattivato, questo incantesimo non viene mai proposto a nessuno e Automatico lo salta. Tutto il resto continua come prima."
L["Who to buff"] = "Destinatari"
L["Buffs"] = "Benefici"
L["Buff to cast"] = "Beneficio da lanciare"
L["Sources"] = "Chi considerare"
L["Nothing below is switched on, so the prompt will never appear."] = "Nessuna opzione qui sotto è attiva, quindi il riquadro non apparirà mai."
L["People who buffed me"] = "Chi mi ha dato un beneficio"
L["Watch for buffs cast on you and offer to return them. What you cast reaches only your own party -- in a raid, your own subgroup -- so somebody outside it is offered once they join."] = "Tiene d'occhio i benefici lanciati su di te e propone di ricambiarli. Ciò che lanci raggiunge solo il tuo gruppo -- in un'incursione, il tuo sottogruppo -- quindi chi ne è fuori viene proposto quando ci entra."
L["Watch for buffs cast on you and offer to return them. What you cast reaches your group only, so somebody outside it is offered once they join."] = "Tiene d'occhio i benefici lanciati su di te e propone di ricambiarli. Ciò che lanci raggiunge solo il tuo gruppo, quindi chi ne è fuori viene proposto quando ci entra."
L["Watch for buffs cast on you and offer to return them. Works on strangers who are not in your group."] = "Tiene d'occhio i benefici lanciati su di te e propone di ricambiarli. Funziona anche con gli sconosciuti che non sono nel tuo gruppo."
L["Only count real class buffs"] = "Conta solo i veri benefici di classe"
L["A shield, a heal-over-time or a trinket proc is not a favour owed. Leave this on unless you want every incoming aura to count."] = "Uno scudo, una cura periodica o l'attivazione di un monile non è un favore da ricambiare. Lascia attiva l'opzione a meno che tu non voglia contare ogni aura ricevuta."
L["My party and raid"] = "Il mio gruppo e la mia incursione"
L["Nearby players not in my group"] = "Giocatori vicini fuori dal mio gruppo"
L["Offer passers-by who are missing the buff. Seen through nameplates, your target, your focus and your mouseover."] = "Proponi i passanti a cui manca il beneficio. Vengono individuati tramite le barre dei nomi, il tuo bersaglio, il tuo focus e chi hai sotto il cursore."
L["Everything you can offer is cast on yourself and heard by your party, so there is nothing to give a passer-by."] = "Tutto ciò che puoi proporre si lancia su di te e raggiunge il tuo gruppo, quindi non c'è nulla da dare a un passante."
L["People who ask me for it"] = "Chi mi chiede il beneficio"
L["For a minute, offer your buff to somebody who asks for it in /say, /yell, group chat or a whisper -- \"int pls\", \"fort?\", \"buffs please\"."] = "Per un minuto, proponi il tuo beneficio a chi lo chiede in /say, /yell, nella chat del gruppo o con un sussurro -- \"int pls\", \"fort?\", \"buffs please\"."
L["Only short requests count, and in a fight only whispers. Nothing is said back to them."] = "Contano solo le richieste brevi, e in combattimento solo i sussurri. Manners non gli risponde nulla."
L["Off at first: reading chat is guesswork, so now and then somebody only talking about a buff is offered one."] = "All'inizio è disattivata: leggere la chat è un po' tirare a indovinare, quindi ogni tanto viene proposto anche chi stava solo parlando di un beneficio."
L["Wording: asked for it"] = "Testo: te l'ha chiesto"
L["The prompt's second line for somebody who asked for the buff in chat."] = "La seconda riga del riquadro per chi ha chiesto il beneficio in chat."
L["Who comes first"] = "Chi viene prima"
L["Whoever I have targeted comes first"] = "Prima chi ho come bersaglio"
L["Your target outranks a favour owed, but only when the game can read that they are missing the buff."] = "Il tuo bersaglio passa davanti a un favore da ricambiare, ma solo quando il gioco riesce a leggere che non ha il beneficio."
L["Not while |cffffd100If they already have the buff|r is set to Always offer, under When, since nothing is read then."] = "Non quando |cffffd100Se hanno già il beneficio|r è su Proponi sempre, nella scheda Quando, perché in quel caso non si legge nulla."
L["Mouseover is left out: the prompt would flicker as the cursor crossed the screen."] = "Il passaggio del mouse è escluso: il riquadro sfarfallerebbe mentre il cursore attraversa lo schermo."
L["My friends and guildmates come before the others"] = "Prima i miei amici e compagni di gilda"
L["A friend or guildmate goes ahead of the other passers-by, or of the rest of your group. It only changes the order; nobody is added or left out."] = "Un amico o un compagno di gilda viene prima degli altri passanti, o del resto del tuo gruppo. Cambia solo l'ordine; nessuno viene aggiunto né escluso."
L["Friends include Battle.net friends. When the game will not say whether somebody is a friend, they are ranked like anybody else."] = "Gli amici includono gli amici Battle.net. Quando il gioco non dice se qualcuno è un amico, viene ordinato come chiunque altro."
L["Who to skip"] = "Chi saltare"
L["Mana-only buffs such as Arcane Intellect, Wisdom and Divine Spirit are wasted on warriors and rogues."] = "I benefici che servono solo a chi usa il mana, come Intelletto Arcano, Saggezza e Spirito Divino, sono sprecati su guerrieri e ladri."
L["Hide players known to be out of range"] = "Nascondi i giocatori che risultano fuori portata"
L["When the game will not tell us the range -- common on this client -- they are still offered."] = "Quando il gioco non ci dice la portata -- cosa frequente su questo client -- vengono proposti comunque."
L["How near a passer-by has to be"] = "Quanto vicino deve essere un passante"
L["Being in range is not the same as being near: Arcane Intellect and its like reach about thirty yards, which in a city is everybody on the screen."] = "Essere a portata non vuol dire essere vicini: Intelletto Arcano e simili arrivano a circa trenta metri, cioè in città tutti quelli sullo schermo."
L["|cffffd100Anywhere I can cast|r -- about thirty yards, as it was."] = "|cffffd100Ovunque io possa lanciare|r -- circa trenta metri, come prima."
L["|cffffd100Nearby|r -- about ten yards."] = "|cffffd100Vicino|r -- circa dieci metri."
L["|cffffd100Right beside me|r -- about five yards."] = "|cffffd100Proprio accanto a me|r -- circa cinque metri."
L["Only passers-by are measured; not somebody who buffed you, your group, or whoever you targeted or focused."] = "Si misurano solo i passanti; non chi ti ha dato un beneficio, né il tuo gruppo, né chi hai come bersaglio o focus."
L["The game gives no exact distance, so this is measured as closely as the client allows. When it cannot measure at all, everybody in casting range is offered."] = "Il gioco non dà una distanza esatta, quindi la si misura con la precisione che il client consente. Quando non riesce a misurare affatto, vengono proposti tutti quelli a portata di lancio."
L["Only offer passers-by in cities and inns"] = "Proponi i passanti solo in città e nelle locande"
L["Out in the world, passers-by are left alone; they are offered only where the game shows you as resting, which is in a city or an inn."] = "In giro per il mondo i passanti vengono lasciati stare; vengono proposti solo dove il gioco ti segna a riposo, cioè in città o in una locanda."
L["Somebody who buffed you, your group, and whoever you have targeted or focused are offered anywhere."] = "Chi ti ha dato un beneficio, il tuo gruppo e chi hai come bersaglio o focus vengono proposti ovunque."
L["If the game will not say whether you are resting, passers-by are offered as usual."] = "Se il gioco non dice se sei a riposo, i passanti vengono proposti come al solito."
L["Drop people who are probably gone"] = "Togli chi probabilmente se n'è andato"
L["Somebody who buffed you can rarely be range-checked afterwards. With this on, they count as in range for a while after their buff, then are let go."] = "Dopo che qualcuno ti ha dato un beneficio, di rado si può verificare se è a portata. Con questa opzione attiva, viene considerato a portata per un po' dopo il suo beneficio, poi viene tolto."
L["Let them go after (seconds)"] = "Toglili dopo (secondi)"
L["How long somebody counts as in range after they buff you. It runs from their buff, not from when they walk off."] = "Per quanto tempo qualcuno viene considerato a portata dopo che ti ha dato un beneficio. Il tempo parte dal suo beneficio, non da quando si allontana."
L["Minimum level"] = "Livello minimo"
L["Players below this are never offered. Somebody known only by name cannot be level-checked and is offered anyway."] = "I giocatori sotto questo livello non vengono mai proposti. Di chi si conosce solo il nome non si può verificare il livello, quindi viene proposto comunque."
L["Never offer"] = "Mai proporre"
L["Nobody is on the list. Shift-right-click the prompt to put whoever it is showing on it, or add a name below."] = "Non c'è nessuno nell'elenco. Fai Maiusc+clic destro sul riquadro per aggiungere chi sta mostrando, oppure aggiungi un nome qui sotto."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Nell'elenco c'è una persona. Non le viene mai proposto nulla, né come passante né come membro del tuo gruppo."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "Nell'elenco ci sono %d persone. Non viene mai proposto loro nulla, né come passanti né come membri del tuo gruppo."
L["Somebody on it who buffs you is still offered the favour back. Shift-right-click them on the prompt to let that favour go."] = "Chi è nell'elenco e ti dà un beneficio viene comunque proposto per ricambiare il favore. Fai Maiusc+clic destro sul suo nome nel riquadro per lasciar perdere quel favore."
L["Add somebody by name"] = "Aggiungi qualcuno per nome"
L["Spelled the way the prompt shows them. Capitals do not matter."] = "Scritto come lo mostra il riquadro. Maiuscole e minuscole non contano."
L["On the list"] = "Nell'elenco"
L["Take them off"] = "Togli dagli esclusi"
L["Clear the list"] = "Svuota l'elenco"
L["Take everybody off the never-offer list?"] = "Togliere tutti dall'elenco degli esclusi?"
L["General"] = "Generale"
L["Enable"] = "Attiva"
L["Manners is switched off, so the prompt will never appear. Everything below is still saved."] = "Manners è disattivato, quindi il riquadro non apparirà mai. Tutto ciò che è qui sotto resta salvato."
L["Your class has no buffs it can cast on another player."] = "La tua classe non ha benefici da lanciare su un altro giocatore."
L["Manners has nothing to offer here. It is still worth keeping installed on an alt that does."] = "Qui Manners non ha nulla da proporre. Vale comunque la pena tenerlo installato per un altro personaggio che invece ne ha."
L["Manners could not work out what you can cast."] = "Manners non è riuscito a capire cosa puoi lanciare."
L["Either your class has nothing for other players, or the spell probe came back empty -- %s says which."] = "O la tua classe non ha nulla per gli altri giocatori, o la verifica degli incantesimi non ha trovato nulla -- %s ti dice quale dei due."
L["How this works"] = "Come funziona"
L["Blizzard does not let an addon cast a spell by itself, so Manners works out who deserves a buff and puts them on the prompt. Click the prompt and it casts."] = "Blizzard non permette a un add-on di lanciare un incantesimo da solo, quindi Manners capisce chi merita un beneficio e lo mette nel riquadro. Fai clic sul riquadro e parte il lancio."
L["Putting it on a key"] = "Assegnarlo a un tasto"
L["Make the macro below and drag it onto a bar, or bind a key under Options > Keybindings > Manners."] = "Crea la macro qui sotto e trascinala su una barra, oppure assegna un tasto in Opzioni > Assegnazione tasti > Manners."
L["Getting started"] = "Per iniziare"
L["Create the macro"] = "Crea la macro"
L["Adds a macro called Manners containing %s. Drag it onto an action bar and it fires the prompt."] = "Aggiunge una macro chiamata Manners che contiene %s. Trascinala su una barra delle azioni: premerla equivale a fare clic sul riquadro."
L["Snooze"] = "Pausa"
L["|cffffd100Snoozed until %s.|r In a fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "|cffffd100In pausa fino alle %s.|r Durante il combattimento il riquadro resta com'era all'inizio, e segue la pausa quando il combattimento finisce."
L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged, casting nothing, until you lock it."] = "|cffffd100In pausa fino alle %s.|r Il riquadro è sbloccato, quindi resta visibile per essere trascinato, senza lanciare niente, finché non lo blocchi."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100In pausa fino alle %s.|r Fino ad allora niente riquadro, ma chi ti dà un beneficio viene comunque notato."
L["Keep the prompt out of the way for a while without switching Manners off. It comes back when the time is up, or after a %s."] = "Tieni il riquadro fuori dai piedi per un po' senza disattivare Manners. Torna allo scadere del tempo, o dopo un %s."
L["Stop snoozing"] = "Termina la pausa"
L["Minimap"] = "Minimappa"
L["Show minimap button"] = "Mostra il pulsante della minimappa"
L["Manners stays in the addon compartment under the minimap either way."] = "In ogni caso Manners resta nel menu degli add-on sotto la minimappa."
L["Without it, |cffffd100/manners|r and the AddOns page in the game's options are the way in."] = "Senza, per aprire Manners ci sono |cffffd100/manners|r e la pagina degli add-on nelle opzioni del gioco."
L["Chat"] = "Chat"
L["Tell me in chat what the addon is doing"] = "Dimmi in chat cosa fa l'add-on"
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Una riga quando qualcuno ti dà un beneficio, quando un favore è considerato ricambiato, e quando un clic fallisce, viene saltato o lascia un favore ancora da ricambiare."
L["Only you see these lines. They tell a buff that was never noticed apart from somebody who could not be reached."] = "Queste righe le vedi solo tu. Servono a distinguere un beneficio mai notato da un giocatore che non si poteva raggiungere."
L["Share settings"] = "Condividi impostazioni"
L["Copy these settings as one line of text, or paste one you were given."] = "Copia queste impostazioni come una riga di testo, oppure incollane una che ti hanno dato."
L["A paste leaves your on switch, lock, prompt position, click log and minimap button alone. It never switches on speaking, and while speaking is on, what you say and where stays yours."] = "Una riga incollata non cambia lo stato di Manners, il blocco e la posizione del riquadro, il log dei clic né il pulsante della minimappa. Non attiva mai le frasi, e se le hai attive, cosa dici e dove resta come l'hai scelto tu."
L["Hide the text"] = "Nascondi il testo"
L["Show my settings as text"] = "Mostra le mie impostazioni come testo"
L["Shows these settings as one line of text in a box below, ready to select and copy. %s opens it too."] = "Mostra queste impostazioni come una riga di testo in una casella qui sotto, pronta da selezionare e copiare. Si apre anche con %s."
L["Click in the box, press Ctrl+A to select it all, then Ctrl+C to copy (Cmd on a Mac)."] = "Fai clic nella casella, premi Ctrl+A per selezionare tutto, poi Ctrl+C per copiare (Cmd su Mac)."
L["Paste settings to use them"] = "Incolla le impostazioni per usarle"
L["Replaces the settings on this profile with the ones in the text. %s puts yours back."] = "Sostituisce le impostazioni di questo profilo con quelle del testo. %s ripristina le tue."
L["Open the ledger"] = "Apri il registro"
L["Who buffed you and with what, whether you returned it, and who you buffed unasked. Also %s, or shift-click the minimap button."] = "Chi ti ha dato un beneficio e quale, se l'hai ricambiato, e a chi hai dato un beneficio di tua iniziativa. Anche con %s, o con Maiusc+clic sul pulsante della minimappa."
L["Already buffed"] = "Chi ha già il beneficio"
L["If they already have the buff"] = "Se hanno già il beneficio"
L["Reading whether somebody has a buff needs the game's permission. See the Diagnostics tab for which of your buffs qualify."] = "Per leggere se qualcuno ha un beneficio serve il permesso del gioco. Nella scheda Diagnostica trovi quali dei tuoi benefici lo consentono."
L["Somebody who buffed you is offered the favour back whichever you choose, even if they already have it."] = "Chi ti ha dato un beneficio viene proposto per ricambiare il favore qualunque cosa tu scelga, anche se ha già il beneficio."
L["Leave them alone (unless they buffed you)"] = "Lasciali stare (salvo chi ti ha dato un beneficio)"
L["Offer a top-up when it is running out"] = "Proponi un rinnovo quando sta per scadere"
L["Always offer, whatever they have"] = "Proponi sempre, qualunque cosa abbiano"
L["Top up when under (minutes) are left"] = "Rinnova quando mancano meno di (minuti)"
L["Only offer a refresh once their remaining time drops below this. Somebody whose timer cannot be read is left alone, unless they buffed you."] = "Proponi un rinnovo solo quando il tempo rimasto scende sotto questo valore. Chi ha un beneficio di cui non si legge la durata viene lasciato stare, a meno che non te ne abbia dato uno."
L["Everyone nearby will be offered constantly, including people whose buff has barely ticked down. Expect to be spending mana."] = "Tutti i giocatori vicini verranno proposti di continuo, anche chi ha ricevuto il beneficio da pochissimo. Preparati a spendere mana."
L["Nothing is read in this mode, so |cffffd100Whoever I have targeted comes first|r has no effect."] = "In questa modalità non si legge nulla, quindi |cffffd100Prima chi ho come bersaglio|r non ha effetto."
L["Timing"] = "Tempi"
L["Remember a buff for (seconds)"] = "Ricorda un beneficio per (secondi)"
L["How long a favour is remembered. Somebody the game cannot see may be let go sooner by |cffffd100Drop people who are probably gone|r, under Who to buff."] = "Per quanto tempo si ricorda un favore. Chi il gioco non vede può essere tolto prima da |cffffd100Togli chi probabilmente se n'è andato|r, nella scheda Destinatari."
L["Remember them across a reload"] = "Ricordali anche dopo un ricaricamento"
L["Keep favours owed through a reload or a disconnect. The clock keeps running meanwhile, so a favour that ran out is not brought back."] = "Conserva i favori da ricambiare dopo un ricaricamento o una disconnessione. Il tempo continua a scorrere nel frattempo, quindi un favore scaduto non torna."
L["Stored against this character, never shared between profiles. Switching it off deletes what has already been stored."] = "I dati sono salvati per questo personaggio e mai condivisi tra profili. Disattivando l'opzione si cancella ciò che è già stato salvato."
L["Wait before offering the same spell again (seconds)"] = "Aspetta prima di riproporre lo stesso incantesimo (secondi)"
L["After you click, how long before that spell is offered to that player again. Covers casts that failed out of sight."] = "Dopo il clic, quanto tempo prima che quell'incantesimo venga riproposto a quel giocatore. Copre i lanci falliti senza che tu lo veda."
L["Per spell, not per person: after Fortitude the next scan can still offer them Divine Spirit. Right-clicking the prompt skips the whole person for this long."] = "Per incantesimo, non per persona: dopo Fermezza la scansione successiva può comunque proporgli Spirito Divino. Un clic destro sul riquadro salta l'intera persona per lo stesso tempo."
L["Scan every (seconds)"] = "Scansiona ogni (secondi)"
L["Lower is more responsive and slightly heavier."] = "Un valore più basso è più reattivo e un po' più pesante."
L["Out of the way"] = "Fuori dai piedi"
L["Keep the prompt away while you are on a mount, since casting would take you off it. It comes back when you get off."] = "Tieni lontano il riquadro mentre sei in sella, perché lanciare ti farebbe scendere dalla cavalcatura. Torna quando scendi."
L["It already stays away while you are dead, on a flight path or in a vehicle. In a fight the prompt stays as the fight found it until the fight ends."] = "Resta già nascosto quando sei morto, durante un volo o su un veicolo. Durante il combattimento il riquadro resta com'era all'inizio finché il combattimento non finisce."
L["When you click"] = "Al clic"
L["|cffffd100In combat.|r Blizzard freezes the prompt's macro during a fight, so these settings apply once it ends."] = "|cffffd100In combattimento.|r Blizzard congela la macro del riquadro durante il combattimento, quindi queste impostazioni si applicano quando finisce."
L["Targeting"] = "Bersaglio"
L["Hand my target back afterwards"] = "Ripristina il mio bersaglio dopo il lancio"
L["The prompt targets whoever it buffs, group members too. With this on, your previous target is restored right after the cast."] = "Il riquadro prende come bersaglio chiunque riceva il beneficio, anche i membri del gruppo. Con questa opzione attiva, il tuo bersaglio precedente viene ripristinato subito dopo il lancio."
L["Everything you can offer is cast on yourself and heard by your party, so the prompt never takes your target and has none to hand back."] = "Tutto ciò che puoi proporre si lancia su di te e raggiunge il tuo gruppo, quindi il riquadro non cambia mai il tuo bersaglio e non ha nulla da ripristinare."
L["The prompt runs |cffffd100%s|r, the cast, then |cffffd100%s|r, except outside a fight for somebody already your target, who stays targeted."] = "Il riquadro esegue |cffffd100%s|r, il lancio, poi |cffffd100%s|r, tranne fuori dal combattimento per chi è già il tuo bersaglio, che resta tale."
L["The prompt runs |cffffd100%s|r, then the cast, and leaves them targeted."] = "Il riquadro esegue |cffffd100%s|r, poi il lancio, e il giocatore resta il tuo bersaglio."
L["A %s conditional only reaches your party or raid, so the macro targets everybody it buffs."] = "Una condizione %s raggiunge solo il tuo gruppo o la tua incursione, quindi la macro prende come bersaglio chiunque riceva il beneficio."
L["Speech"] = "Messaggio in chat"
L["Say something when you buff somebody. The line is added to the macro the prompt runs, so it goes out as you talking rather than as an addon."] = "Di' qualcosa quando dai un beneficio a qualcuno. La frase viene aggiunta alla macro eseguita dal riquadro, quindi esce come se parlassi tu e non come un add-on."
L["The game refuses addon-sent %s and %s outside instances, so going through the macro is what lets them work."] = "Fuori dalle istanze il gioco rifiuta i messaggi %s e %s inviati da un add-on, quindi è passare dalla macro che li fa funzionare."
L["Say something"] = "Di' qualcosa"
L["Channel"] = "Canale"
L["Say"] = "Parla"
L["Yell"] = "Urla"
L["Party"] = "Gruppo"
L["Raid"] = "Incursione"
L["Emote"] = "Emote"
L["Only when returning a favour"] = "Solo quando ricambi un favore"
L["Speak only when buffing somebody who buffed you first. Leave this on unless you want to announce every stranger you buff."] = "Parla solo quando dai un beneficio a chi te ne ha dato uno per primo. Lascia attiva l'opzione a meno che tu non voglia annunciare ogni sconosciuto a cui dai un beneficio."
L["Phrases"] = "Frasi"
L["Load a set"] = "Carica un set"
L["Replaces the lines below. Edit them afterwards as much as you like."] = "Sostituisce le frasi qui sotto. Poi puoi modificarle quanto vuoi."
L["Replace everything in the box below with the %s lines?"] = "Sostituire tutto il contenuto della casella qui sotto con le frasi del set %s?"
L["loaded the %s lines."] = "caricate le frasi del set %s."
L["One per line -- a random one is picked each time the prompt changes target. Tokens: |cff888888{name}|r the player, |cff888888{buff}|r the spell."] = "Una per riga -- ne viene scelta una a caso ogni volta che il riquadro cambia bersaglio. Segnaposto: |cff888888{name}|r il giocatore, |cff888888{buff}|r l'incantesimo."
L["A macro holds 255 characters, so a line that will not fit is dropped, not cut off -- |cffffd100Roll a few|r shows what would go out. An empty box goes back to the chosen set."] = "Una macro contiene al massimo 255 caratteri, quindi una frase che non ci sta viene scartata, non tagliata -- |cffffd100Estrai a caso|r mostra cosa uscirebbe. Una casella vuota torna al set scelto."
L["In character: the line is picked when you click, to fit your race, your faction and the moment -- thanks for a favour, an answer to a request, or an offer. Below are a few of this character's lines; edit them and they become your own lines instead."] = "Con questo set la frase viene scelta al clic, in base alla tua razza, alla tua fazione e al momento -- un ringraziamento per un favore, la risposta a una richiesta o una proposta. Qui sotto trovi alcune frasi di questo personaggio; se le modifichi, diventano invece frasi tue."
L["Roll a few"] = "Estrai a caso"
L["Somebody"] = "Qualcuno"
L["A line goes out when you click, even if the cast then fails out of range or line of sight."] = "La frase parte al clic, anche se poi il lancio fallisce perché il bersaglio è fuori portata o fuori dalla linea di vista."
L["Prompt"] = "Riquadro"
L["|cffffd100In combat.|r Blizzard freezes secure frames, so changes here are saved and appear once the fight ends."] = "|cffffd100In combattimento.|r Blizzard congela i riquadri protetti, quindi le modifiche fatte qui vengono salvate e compaiono quando il combattimento finisce."
L["Stop preview"] = "Ferma l'anteprima"
L["Preview"] = "Anteprima"
L["Show a sample entry to style the prompt by. It stays while this window is open, then twenty seconds more or until somebody real turns up."] = "Mostra un esempio su cui personalizzare il riquadro. Resta finché questa finestra è aperta, poi altri venti secondi o finché non arriva qualcuno in carne e ossa."
L["Locked"] = "Bloccato"
L["Unlock to drag the prompt. It will not cast while unlocked."] = "Sblocca per trascinare il riquadro. Mentre è sbloccato non lancia niente."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "sbloccato, ma l'add-on è |cffff8080disattivato|r, quindi non c'è nessun riquadro da trascinare -- prima attivalo."
L["Reset position"] = "Ripristina posizione"
L["Style"] = "Stile"
L["Where the reason colour goes"] = "Dove va il colore del motivo"
L["A ring around the icon reads better than a stripe at the panel edge, which ends up competing with the icon rather than framing it."] = "Un anello attorno all'icona si legge meglio di una striscia sul bordo del pannello, che finisce per fare concorrenza all'icona invece di incorniciarla."
L["The framed look has no stripe at all -- it would run down the inside of its border -- so on it the stripe settings do nothing."] = "L'aspetto Incorniciato non ha nessuna striscia -- correrebbe lungo l'interno del bordo -- quindi lì le impostazioni della striscia non hanno effetto."
L["Ring around the icon"] = "Anello attorno all'icona"
L["Stripe down the left edge"] = "Striscia sul bordo sinistro"
L["Both"] = "Entrambi"
L["Neither"] = "Nessuno dei due"
L["Colour it by reason"] = "Colora in base al motivo"
L["Pale yellow for your own target, orange for a favour owed, deep pink for somebody who asked, sky blue for your group, violet for passers-by -- the order they are offered in."] = "Giallo chiaro per il tuo bersaglio, arancione per un favore da ricambiare, rosa intenso per chi l'ha chiesto, celeste per il tuo gruppo, viola per i passanti -- l'ordine in cui vengono proposti."
L["Pale blue for your own target, amber for a favour owed, pink for somebody who asked, deeper blue for your group, grey for passers-by -- the order they are offered in."] = "Azzurro chiaro per il tuo bersaglio, ambra per un favore da ricambiare, rosa per chi l'ha chiesto, blu più scuro per il tuo gruppo, grigio per i passanti -- l'ordine in cui vengono proposti."
L["The first of those appears only while |cffffd100Whoever I have targeted comes first|r is on and |cffffd100If they already have the buff|r is not Always offer."] = "Il primo compare solo quando |cffffd100Prima chi ho come bersaglio|r è attiva e |cffffd100Se hanno già il beneficio|r non è su Proponi sempre."
L["Reason colours"] = "Colori dei motivi"
L["The colour-blind set keeps the reasons apart for red-green colour blindness, in colours that differ in lightness too."] = "I colori per daltonici tengono distinti i motivi in caso di daltonismo rosso-verde, con colori che differiscono anche per luminosità."
L["Standard"] = "Standard"
L["Colour-blind friendly"] = "Adatti ai daltonici"
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off, and the framed look has no stripe."] = "Non resta niente da colorare: l'anello è disegnato dietro l'icona, che è disattivata, e l'aspetto Incorniciato non ha la striscia."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask, and the framed look has no stripe."] = "Non resta niente da colorare: arrotondare l'icona sostituisce l'anello con una maschera, e l'aspetto Incorniciato non ha la striscia."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off."] = "Non resta niente da colorare: l'anello è disegnato dietro l'icona, che è disattivata."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask."] = "Non resta niente da colorare: arrotondare l'icona sostituisce l'anello con una maschera."
L["There is nothing left to colour: the framed look has no stripe."] = "Non resta niente da colorare: l'aspetto Incorniciato non ha la striscia."
L["Accent colour"] = "Colore di risalto"
L["Used for the ring, the stripe, or both -- whichever the setting above asks for."] = "Usato per l'anello, la striscia o entrambi -- secondo quanto chiede l'impostazione qui sopra."
L["Look"] = "Aspetto"
L["Glass -- dark panel, soft shadow"] = "Vetro -- pannello scuro, ombra morbida"
L["Framed -- flat panel, thin border"] = "Incorniciato -- pannello piatto, bordo sottile"
L["Minimal -- text only, no panel"] = "Minimale -- solo testo, niente pannello"
L["Panel colour"] = "Colore del pannello"
L["Getting your attention"] = "Attirare l'attenzione"
L["When someone buffs you"] = "Quando qualcuno ti dà un beneficio"
L["Pulse keeps breathing until you have returned the favour or they are gone. Flash once is easy to miss if you were looking elsewhere."] = "La pulsazione continua finché non ricambi il favore o finché il giocatore non se ne va. Un solo lampeggio si perde facilmente se stavi guardando altrove."
L["It lights the spell icon, sweeps the stripe, and with Effects on Full the panel catches the light. With none of those showing it has nothing to do."] = "Illumina l'icona dell'incantesimo, percorre la striscia e, con Effetti su Completi, fa illuminare il pannello. Se nessuno di questi è visibile, non ha niente su cui agire."
L["Pulse until dealt with"] = "Pulsa finché non te ne occupi"
L["Flash once"] = "Lampeggia una volta"
L["Nothing"] = "Niente"
L["Effects"] = "Effetti"
L["Full: light crosses the panel when a buff lands, a refused buff shakes the text, and the prompt fades out after your last buff."] = "Completi: una luce attraversa il pannello quando un beneficio va a segno, un beneficio rifiutato fa tremare il testo, e dopo il tuo ultimo beneficio il riquadro svanisce in dissolvenza."
L["Calm: none of that movement. The prompt still fades in, and the glow set above still works."] = "Calmi: nessuno di questi movimenti. Il riquadro compare comunque in dissolvenza, e il bagliore impostato qui sopra funziona ancora."
L["The Minimal look has no panel, so no light crosses it. In a fight, Stay quiet in combat keeps the outcome still as well."] = "L'aspetto Minimale non ha pannello, quindi nessuna luce lo attraversa. In combattimento, con Discreto in combattimento anche l'esito resta senza animazione."
L["Full"] = "Completi"
L["Calm -- less movement"] = "Calmi -- meno movimento"
L["Play a sound"] = "Riproduci un suono"
L["Play a sound when somebody new reaches the top of the queue."] = "Riproduci un suono quando qualcuno di nuovo arriva in cima alla coda."
L["Sound"] = "Suono"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(non caricato)|r"
L["Only when somebody buffed me"] = "Solo quando qualcuno mi ha dato un beneficio"
L["Off, every new person on the prompt makes a noise -- including strangers you happen to walk past."] = "Se è disattivata, ogni nuova persona nel riquadro fa partire il suono -- compresi gli sconosciuti accanto a cui ti capita di passare."
L["%s is silent. Pick a sound above."] = "%s è muto. Scegli un suono qui sopra."
L["Position and size"] = "Posizione e dimensioni"
L["Put it"] = "Posizionalo"
L["Three places that are already right. Dragging the prompt afterwards leaves this blank, because it is then not on one of them."] = "Tre posizioni già giuste. Se poi trascini il riquadro, questo campo resta vuoto, perché il riquadro non è più in nessuna di esse."
L["X offset"] = "Spostamento X"
L["Y offset"] = "Spostamento Y"
L["Width"] = "Larghezza"
L["Height"] = "Altezza"
L["Scale"] = "Scala"
L["Opacity"] = "Opacità"
L["Stay quiet in combat"] = "Discreto in combattimento"
L["A click still casts in combat, and the prompt flashes to say what happened -- red if it failed. With this on it stays dimmed and still for the fight."] = "In combattimento un clic lancia comunque, e il riquadro lampeggia per dirti com'è andata -- in rosso se non è riuscito. Con questa opzione attiva resta attenuato e immobile per tutto il combattimento."
L["It stays on screen in a fight on purpose: your key binding would still cast the frozen macro if it were hidden."] = "In combattimento resta sullo schermo di proposito: se fosse nascosto, il tuo tasto assegnato lancerebbe comunque la macro congelata."
L["Text"] = "Testo"
L["First line"] = "Prima riga"
L["Tokens: {name} {reason} {count} {class} {buff} {time}"] = "Segnaposto: {name} {reason} {count} {class} {buff} {time}"
L["Show a second line"] = "Mostra una seconda riga"
L["Needs a prompt at least %d pixels tall at this font size."] = "Con questa dimensione del carattere serve un riquadro alto almeno %d pixel."
L["|cff888888{name}|r who   |cff888888{reason}|r why   |cff888888{count}|r how many more   |cff888888{class}|r their class   |cff888888{buff}|r the spell"] = "|cff888888{name}|r chi   |cff888888{reason}|r perché   |cff888888{count}|r quanti altri   |cff888888{class}|r la sua classe   |cff888888{buff}|r l'incantesimo"
L["|cff888888{time}|r what theirs has left, on a top-up and nowhere else"] = "|cff888888{time}|r quanto resta al suo, solo nei rinnovi"
L["The second line always shows the reason."] = "La seconda riga mostra sempre il motivo."
L["Wording: your target"] = "Testo: il tuo bersaglio"
L["Your target outranks everyone, including a favour owed, while that is switched on under Who to buff and the game can see they lack it."] = "Il tuo bersaglio passa davanti a tutti, anche a un favore da ricambiare, se l'opzione è attiva nella scheda Destinatari e il gioco vede che non ha il beneficio."
L["Wording: buffed you"] = "Testo: ti ha dato un beneficio"
L["Wording: in your group"] = "Testo: nel tuo gruppo"
L["Wording: nearby"] = "Testo: vicino"
L["Wording: topping one up"] = "Testo: rinnovo"
L["Used instead of the four above when their buff is about to run out, which only the refresh mode offers. |cffffd100{time}|r is how long theirs has left."] = "Usato al posto dei quattro qui sopra quando il beneficio del giocatore sta per scadere: lo propone solo la modalità di rinnovo. |cffffd100{time}|r è quanto manca alla scadenza del suo."
L["Wording: state unknown"] = "Testo: stato sconosciuto"
L["Used when the game will not let addons read whether they already have it."] = "Usato quando il gioco non permette agli add-on di sapere se il giocatore ce l'ha già."
L["Font"] = "Carattere"
L["Font size"] = "Dimensione del carattere"
L["Text colour"] = "Colore del testo"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while |cffffd100Colour names by class|r is on."] = "Se lo lasci bianco, il testo diventa scuro da solo su un pannello chiaro. Gli altri colori vengono usati come li scegli, tranne per i nomi quando |cffffd100Colora i nomi in base alla classe|r è attiva."
L["Colour names by class"] = "Colora i nomi in base alla classe"
L["Icon and queue"] = "Icona e coda"
L["Show spell icon"] = "Mostra l'icona dell'incantesimo"
L["Icon size"] = "Dimensione dell'icona"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Resta dentro il riquadro -- per un'icona più grande, prima rendilo più alto o più largo."
L["The icon is held at %d to fit a prompt %d wide."] = "L'icona è limitata a %d per stare in un riquadro largo %d."
L["The icon is held at %d to fit a prompt %d high."] = "L'icona è limitata a %d per stare in un riquadro alto %d."
L["Round the icon off"] = "Arrotonda l'icona"
L["Masks the icon into a circle. Reads more like a portrait than a spell, so it is off by default."] = "Ritaglia l'icona in un cerchio. Sembra più un ritratto che un incantesimo, quindi è disattivata in modo predefinito."
L["The mask replaces the ring, so move the reason colour to the stripe if you want both. The glow when somebody buffs you follows the circle."] = "La maschera sostituisce l'anello, quindi sposta il colore del motivo sulla striscia se vuoi entrambi. Il bagliore quando qualcuno ti dà un beneficio segue il cerchio."
L["Show the global cooldown on the icon"] = "Mostra il tempo di recupero globale sull'icona"
L["Sweeps the spell icon while the global cooldown runs, like your action bars, so you can see when the next press will go through."] = "Mostra la spirale sull'icona dell'incantesimo durante il tempo di recupero globale, come sulle barre delle azioni, così vedi quando puoi premere di nuovo."
L["Not in a fight while Stay quiet in combat is on."] = "Non in combattimento, se Discreto in combattimento è attivo."
L["Show how many are waiting"] = "Mostra quanti sono in attesa"
L["List the next few below"] = "Elenca i prossimi qui sotto"
L["How many to list"] = "Quanti elencarne"
L["Diagnostics"] = "Diagnostica"
L["Log every click to chat"] = "Scrivi ogni clic in chat"
L["Prints what the button held when you clicked and what the game did with it. Noisy; for working out why a cast did not happen."] = "Scrive cosa conteneva il pulsante al momento del clic e cosa ne ha fatto il gioco. Produce molti messaggi; serve a capire perché un lancio non è avvenuto."
L["What this client allows"] = "Cosa permette questo client"
L["Class: |cffffffff%s|r"] = "Classe: |cffffffff%s|r"
L["learned: |cff00ff00yes|r"] = "imparato: |cff00ff00sì|r"
L["learned: |cff808080no|r"] = "imparato: |cff808080no|r"
L["missing-check: |cff00ff00works|r"] = "verifica del beneficio: |cff00ff00funziona|r"
L["missing-check: |cffff8080blocked|r"] = "verifica del beneficio: |cffff8080non consentita|r"
L["this client has never heard of spell %s, so Manners will never offer this one. That is a mistake in Manners -- please report it."] = "questo client non conosce l'incantesimo %s, quindi Manners non lo proporrà mai. È un errore di Manners -- segnalalo, per favore."
L["this client doesn't know spell %s, so somebody already carrying that version may be offered this anyway. That is a mistake in Manners -- please report it."] = "questo client non conosce l'incantesimo %s, quindi questo beneficio potrebbe essere proposto comunque a chi ha già quella variante. È un errore di Manners -- segnalalo, per favore."
L["Where the missing-check is blocked, addons cannot read that aura: players are still offered, but some may already have the buff."] = "Dove la verifica del beneficio non è consentita, gli add-on non possono leggere quell'aura: i giocatori vengono proposti lo stesso, ma alcuni potrebbero avere già il beneficio."
L["Nothing to report: this character has no buffs it can put on another player."] = "Niente da segnalare: questo personaggio non ha benefici da dare ad altri giocatori."
L["What has broken"] = "Cosa è andato storto"
L["(%d in all this session, %d kept -- |cffffd100%s|r)"] = "(%d in tutto in questa sessione, %d conservati -- |cffffd100%s|r)"
L["(%d in all this session -- |cffffd100%s|r)"] = "(%d in tutto in questa sessione -- |cffffd100%s|r)"
L["Nothing has broken this session."] = "In questa sessione non è andato storto niente."
L["Reporting a bug"] = "Segnalare un bug"
L["Hide the report"] = "Nascondi la segnalazione"
L["Copy for a bug report"] = "Copia per segnalare un bug"
L["Opens a box with the build, what this client allows, the settings that matter and anything that has broken, ready to copy."] = "Apre una casella con il numero di versione, cosa permette questo client, le impostazioni che contano e tutto ciò che è andato storto, pronta da copiare."
L["Switched off -- the prompt this fight froze stays up until it ends, and a press still casts it."] = "Disattivato -- il riquadro che questo combattimento ha congelato resta visibile fino alla fine del combattimento, e premendo lanci ancora ciò che mostra."
L["Switched off -- no prompt will appear."] = "Disattivato -- non comparirà nessun riquadro."
L["Unlocked, but in this fight the prompt stays as the fight found it, and a press still casts it; it can be dragged once the fight ends."] = "Sbloccato, ma in questo combattimento il riquadro resta com'era all'inizio, e premendo lanci ancora ciò che mostra; potrai trascinarlo quando il combattimento finisce."
L["Unlocked -- the prompt this fight froze stays up until it ends, and a press still casts it; then it can be dragged."] = "Sbloccato -- il riquadro che questo combattimento ha congelato resta visibile fino alla fine del combattimento, e premendo lanci ancora ciò che mostra; poi potrai trascinarlo."
L["Unlocked, and snoozed until %s -- the prompt stays up to be dragged, casting nothing, until you lock it."] = "Sbloccato e in pausa fino alle %s -- il riquadro resta visibile per essere trascinato, senza lanciare niente, finché non lo blocchi."
L["Unlocked -- the prompt is up to be dragged and casts nothing until you lock it (%s)."] = "Sbloccato -- il riquadro è visibile per essere trascinato e non lancia niente finché non lo blocchi (%s)."
